function alternarTema(){const t=document.body,e=document.getElementById("theme-icon");"light"===t.getAttribute("data-theme")?(t.setAttribute("data-theme","dark"),e.textContent="☀️",localStorage.setItem("theme","dark")):(t.setAttribute("data-theme","light"),e.textContent="🌙",localStorage.setItem("theme","light"))}const savedTheme=localStorage.getItem("theme");savedTheme&&(document.body.setAttribute("data-theme",savedTheme),document.getElementById("theme-icon").textContent="light"===savedTheme?"🌙":"☀️");